  {W : T.Opens} (hW : IsAffineOpen W) [Module.Flat ↑Γ(T, W) ↑Γ(G, W)] [Module.Finite ↑Γ(T, W) ↑Γ(G, W)]
  (p : PrimeSpectrum ↑Γ(T, W)), rankAtStalk (↑Γ(G, W)) p = Scheme.Modules.pointRank T G (hW.fromSpec p)

